// 错误版本：缺少 volatile，可能返回半初始化对象
public class Singleton {
    private static Singleton instance;          // 少了 volatile

    public static Singleton getInstance() {
        if (instance == null) {                 // 第一次检查，无锁
            synchronized (Singleton.class) {
                if (instance == null) {         // 第二次检查，有锁
                    instance = new Singleton(); // 三步操作可能被重排
                }
            }
        }
        return instance;
    }
}

// 正确版本：加 volatile 禁止重排
public class SingletonFixed {
    private static volatile SingletonFixed instance;   // 关键

    public static SingletonFixed getInstance() {
        SingletonFixed local = instance;
        if (local == null) {
            synchronized (SingletonFixed.class) {
                local = instance;
                if (local == null) {
                    instance = local = new SingletonFixed();
                }
            }
        }
        return local;
    }
}

