// volatile 保证可见性：一个线程改，另一个线程能立刻看到
public class Worker {
    private volatile boolean running = true;   // 去掉 volatile 可能死循环

    public void stop() { running = false; }

    public void run() {
        long count = 0;
        while (running) {                      // 每次循环都读 running
            count++;
        }
        System.out.println("退出，count=" + count);
    }
}

