// 锁模型要点
// 每个对象天生一把锁（monitor），任何对象都能当 synchronized(obj) 的锁
// synchronized 方法：进入前必须拿到该对象的钥匙；退出时自动释放（即使抛异常）
//
// 锁是「每对象一把」，不是「每方法一把」：
class Shared {
  synchronized void m1() {}   // 同一对象的 m1、m2、m3 共用一把锁
  synchronized void m2() {}   // 一条线程在 m1 里，别人 m2/m3 都进不去
  synchronized void m3() {}
}
//
// 你锁的不是数据本身（不能写 synchronized int balance），而是访问数据的代码
// 所有会读写同一份数据的路径，必须用同一把锁保护 —— 漏一条就有缺口
// 锁可重入：同一线程可重复进入自己已持有的锁（同步方法调同步方法不会自锁）
// Java 没有加锁 API：JVM 进出同步块自动获取/释放锁
// 休息室：拿不到锁的线程进等待区（BLOCKED），不占 CPU

// 原子变量：单值的无锁原子操作
AtomicInteger balance = new AtomicInteger(0);
balance.incrementAndGet();   // 原子加一，不必 synchronized

// CAS = compareAndSet(expected, newValue)：仅当当前值==expected 才改成 newValue
// 比较+交换由 CPU 原子指令保证不可分割；返回 boolean 表示成没成
private final AtomicInteger balance = new AtomicInteger(100);
public void spend(String name, int amount) {
  int initialBalance = balance.get();              // 记下「我以为的余额」
  if (initialBalance >= amount) {
    boolean success = balance.compareAndSet(initialBalance, initialBalance - amount);
    if (!success) System.out.println("Sorry " + name + ", you haven't spent the money.");
    // false = 有人改过，这次没扣成 —— 由你决定重试还是报错
  }
}
